{
  "name": "@velum-labs/routekit-tool-opencode",
  "private": false,
  "version": "1.5.2",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/velum-labs/routekit.git",
    "directory": "packages/tool-opencode"
  },
  "description": "Product-neutral OpenCode launcher, serializer, and canonical harness driver.",
  "license": "Apache-2.0",
  "type": "module",
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "default": "./dist/index.js"
    },
    "./driver": {
      "types": "./dist/driver.d.ts",
      "default": "./dist/driver.js"
    },
    "./launch": {
      "types": "./dist/launch.d.ts",
      "default": "./dist/launch.js"
    }
  },
  "files": [
    "dist",
    "LICENSE"
  ],
  "publishConfig": {
    "registry": "https://registry.npmjs.org",
    "access": "public",
    "provenance": true
  },
  "dependencies": {
    "@opencode-ai/sdk": "1.17.13",
    "undici": "8.10.1",
    "zod": "4.4.3",
    "@velum-labs/routekit-contracts": "1.5.2",
    "@velum-labs/routekit-harness-core": "1.5.2",
    "@velum-labs/routekit-tools": "1.5.2",
    "@velum-labs/routekit-runtime": "1.5.2"
  },
  "keywords": [
    "llm",
    "coding-agent",
    "opencode",
    "harness",
    "adapter"
  ],
  "scripts": {
    "build": "tsc -p tsconfig.json",
    "clean": "tsc -b --clean",
    "test": "node --test \"dist/test/*.test.js\""
  }
}
